<?php declare(strict_types=1); namespace App\People\Infrastructure\Persistence\DBAL; use App\People\Domain\Enum\RelationshipType; use App\People\Domain\Model\PersonRelationship; use App\People\Domain\ValueObject\PersonId; use App\People\Domain\ValueObject\RelationshipId; use App\Shared\Domain\ValueObject\AuditTimestamps; final class RelationshipMapper {public function toDomain(array $r):PersonRelationship{return PersonRelationship::reconstitute(RelationshipId::fromString((string)$r['id']),PersonId::fromString((string)$r['person_id']),PersonId::fromString((string)$r['related_person_id']),RelationshipType::from((string)$r['type']),$r['ended_at']?new \DateTimeImmutable((string)$r['ended_at']):null,new AuditTimestamps(new \DateTimeImmutable((string)$r['created_at']),new \DateTimeImmutable((string)$r['updated_at'])));} public function toRow(PersonRelationship $r):array{return ['id'=>$r->id()->toString(),'person_id'=>$r->personId()->toString(),'related_person_id'=>$r->relatedPersonId()->toString(),'type'=>$r->type()->value,'ended_at'=>$r->endedAt()?->format('Y-m-d H:i:s'),'created_at'=>$r->createdAt()->format('Y-m-d H:i:s'),'updated_at'=>$r->updatedAt()->format('Y-m-d H:i:s')];}}
